import { describe, expect, test } from "bun:test";
import { existsSync, readFileSync } from "node:fs";

import { registryItemSchema } from "shadcn/schema";

/**
 * Guards the committed public registry (`public/r`) that `shadcn add` installs
 * from. It is generated by `bun run registry:build` and committed, so it goes
 * stale silently whenever a component changes without a rebuild: installs then
 * ship old source or miss new dependencies. Fail instead, pointing at the fix.
 */

interface ItemFile {
  path: string;
  content: string;
}

const registry: { items: { name: string }[] } = JSON.parse(
  readFileSync("registry.json", "utf8"),
);

const built = (name: string) => `public/r/${name}.json`;

describe("public registry", () => {
  test("every registry item is built", () => {
    const missing = registry.items
      .map((item) => item.name)
      .filter((name) => !existsSync(built(name)));

    expect(missing).toEqual([]);
  });

  test("every built item matches the shadcn registry item schema", () => {
    const invalid = registry.items
      .map((item) => item.name)
      .filter(
        (name) =>
          existsSync(built(name)) &&
          !registryItemSchema.safeParse(
            JSON.parse(readFileSync(built(name), "utf8")),
          ).success,
      );

    expect(invalid).toEqual([]);
  });

  test("built items ship the current source (run `bun run registry:build`)", () => {
    const stale: string[] = [];

    for (const { name } of registry.items) {
      if (!existsSync(built(name))) continue;

      const { files } = JSON.parse(readFileSync(built(name), "utf8")) as {
        files: ItemFile[];
      };

      for (const file of files)
        if (file.content !== readFileSync(file.path, "utf8"))
          stale.push(`${name}: ${file.path}`);
    }

    expect(stale).toEqual([]);
  });
});
